def perguntar(texto, padrao):
    try:
        r = input("   %s [%s]: " % (texto, padrao)).strip()
    except EOFError:
        r = ""
    return r or padrao


def so_digitos(x, nome):
    x = x.strip()
    if not x.isdigit():
        raise Falha("%s precisa ser só números." % nome)
    return x


